export type listCommunityPostsResponse200 = {
  data: ListPostsResponseBody
  status: 200
}

export type listCommunityPostsResponseDefault = {
  data: ErrorModel
  status: Exclude<HTTPStatusCodes, 200>
}

export type listCommunityPostsResponseSuccess = (listCommunityPostsResponse200) & {
  headers: Headers;
};
export type listCommunityPostsResponseError = (listCommunityPostsResponseDefault) & {
  headers: Headers;
};

export type listCommunityPostsResponse = (listCommunityPostsResponseSuccess | listCommunityPostsResponseError)

export const getListCommunityPostsUrl = (id: string,
    params?: ListCommunityPostsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/v1/community/threads/${id}/posts?${stringifiedParams}` : `/api/v1/community/threads/${id}/posts`
}

export const listCommunityPosts = async (id: string,
    params?: ListCommunityPostsParams, options?: RequestInit): Promise<listCommunityPostsResponse> => {
  
  const res = await fetch(getListCommunityPostsUrl(id,params),
  {      
    ...options,
    method: 'GET'
    
    
  }
)

  const body = [204, 205, 304].includes(res.status) ? null : await res.text();
  
  const data: listCommunityPostsResponse['data'] = body ? JSON.parse(body) : {}
  return { data, status: res.status, headers: res.headers } as listCommunityPostsResponse
}
  

